        if role == "pursuer":
            return move_toward(self_p, opp_p)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = farthest(opp_p, corners) or farthest(self_p, corners)
        return move_toward(self_p, target) if target else [0, 0]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("territory_targets")
            or observation.get("frontier_cells")
            or []
        )
        goals = extract_points(targets)
        if goals:
            # Prefer the nearest usable target, but avoid stepping directly into opponent if nearby.
            best_move = [0, 0]
            best_score = None
            danger = [opp_p] if isinstance(observation.get("opponent_position"), (list, tuple, dict)) else []
            for mv in candidate_moves():
                np = (sx + mv[0], sy + mv[1])
                sc = score_cell(np, goals, danger, gw, gh)
                if best_score is None or sc > best_score:
                    best_score = sc
                    best_move = mv
            return best_move
        if isinstance(observation.get("opponent_position"), (list, tuple, dict)):
            return move_toward(self_p, opp_p)
        return [0, 0]

    # resource_collection and fallback modes
    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    goals = extract_points(resources)
    if goals:
        best_move = [0, 0]
        best_score = None
        danger = []
        if isinstance(observation.get("opponent_position"), (list, tuple, dict)):
            danger = [opp_p]
        for mv in candidate_moves():
            np = (sx + mv[0], sy + mv[1])
            sc = score_cell(np, goals, danger, gw, gh)
            if best_score is None or sc > best_score:
                best_score = sc
                best_move = mv
        return best_move

    # If no resources visible, move away from opponent if close, else hold.
    if isinstance(observation.get("opponent_position"), (list, tuple, dict)):
        d = manhattan(self_p, opp_p)
        if d <= 2:
